class Solution {
private:
    long long countLE(const vector<int>& nums, long long target) {
        long long count = 0, curr = 0;
        int left = 0, n = nums.size();
        for (int right = 0; right < n; right++) {
            curr += nums[right];
            while (curr > target) {
                curr -= nums[left++];
            }
            count += (right - left + 1);
        }
        return count;
    }
public:
    int kthSmallestSubarraySum(vector<int>& nums, int k) {
        long long low = *min_element(nums.begin(), nums.end());
        long long high = accumulate(nums.begin(), nums.end(), 0LL);
        long long ans = high;

        while (low <= high) {
            long long mid = low + (high - low) / 2;
            if (countLE(nums, mid) >= k) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    private long countLE(int[] nums, long target) {
        long count = 0, curr = 0;
        int left = 0, n = nums.length;
        for (int right = 0; right < n; right++) {
            curr += nums[right];
            while (curr > target) {
                curr -= nums[left++];
            }
            count += (right - left + 1);
        }
        return count;
    }

    public int kthSmallestSubarraySum(int[] nums, int k) {
        long low = nums[0], high = 0;
        for (int x : nums) {
            low = Math.min(low, x);
            high += x;
        }
        long ans = high;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (countLE(nums, mid) >= k) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return (int)ans;
    }
}

var kthSmallestSubarraySum = function(nums, k) {
  let low = nums[0], high = 0;
  for (const x of nums) {
    low = Math.min(low, x);
    high += x;
  }
  let ans = high;

  function countLE(target) {
    let count = 0, curr = 0, left = 0;
    for (let right = 0; right < nums.length; right++) {
      curr += nums[right];
      while (curr > target) {
        curr -= nums[left++];
      }
      count += (right - left + 1);
    }
    return count;
  }

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if (countLE(mid) >= k) {
      ans = mid;
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }
  return ans;
};
